def _blade_mul(a: tuple, b: tuple):
    """Geometric product of two sorted basis blades. Returns (sign, blade)."""
    idx = list(a) + list(b)
    sign = 1
    # bubble sort, flipping sign on each swap of UNEQUAL adjacent generators
    n = len(idx)
    for i in range(n):
        for j in range(n - 1 - i):
            if idx[j] > idx[j + 1]:
                idx[j], idx[j + 1] = idx[j + 1], idx[j]
                sign = -sign
    # cancel adjacent equal pairs, applying the signature: e_i^2 = +1 for i in 1..4 (Euclidean
    # substrate), e_5^2 = -1 (the meta-time generator tau5 — Cl(4,1) wave signature, Sec 5.3/L1).
    # For Cl(4,0)-only work (no index 5) this is identical to the old +1 cancellation.
    out = []
    k = 0
    while k < len(idx):
        if k + 1 < len(idx) and idx[k] == idx[k + 1]:
            if idx[k] == 5:
                sign = -sign                 # e_5^2 = -1
            k += 2
        else:
            out.append(idx[k]); k += 1
    return sign, tuple(out)


@dataclass(frozen=True)
class MV:
    """A multivector: map from sorted-index-tuple (a blade) to coefficient."""
    terms: tuple  # tuple of (blade_tuple, coeff), canonicalised

    @staticmethod
    def from_dict(d):
        items = tuple(sorted((b, c) for b, c in d.items() if abs(c) > 1e-12))
        return MV(items)

    def as_dict(self):
        return dict(self.terms)

    def __add__(self, other):
        d = self.as_dict()
        for b, c in other.as_dict().items():
            d[b] = d.get(b, 0.0) + c
        return MV.from_dict(d)

    def __sub__(self, other):
        return self + (-1.0) * other

    def __rmul__(self, s: float):
        return MV.from_dict({b: s * c for b, c in self.terms})

    def __mul__(self, other):
        if isinstance(other, (int, float)):
            return other * self
        d = {}
        for ba, ca in self.terms:
            for bb, cb in other.terms:
                sgn, blade = _blade_mul(ba, bb)
                d[blade] = d.get(blade, 0.0) + sgn * ca * cb
        return MV.from_dict(d)

    def reverse(self):
        """Reverse: blade of grade k gets sign (-1)^(k(k-1)/2)."""
        d = {}
        for b, c in self.terms:
            k = len(b)
            d[b] = c * (-1) ** (k * (k - 1) // 2)
        return MV.from_dict(d)

    def grade(self, k):
        return MV.from_dict({b: c for b, c in self.terms if len(b) == k})

    def coeff(self, blade):
        return dict(self.terms).get(tuple(sorted(blade)), 0.0)

    def __eq__(self, other):
        return self.terms == (other.terms if isinstance(other, MV) else None)

    def __repr__(self):
        if not self.terms:
            return "0"
        parts = []
        for b, c in self.terms:
            name = "1" if not b else "e" + "".join(map(str, b))
            parts.append(f"{c:+.3g}·{name}")
        return " ".join(parts)


def e(*idx) -> MV:
    """[internal helper] Basis blade constructor: e(1,2) -> e12. Handles reordering sign."""
    if not idx:
        return MV.from_dict({(): 1.0})
    out = MV.from_dict({(idx[0],): 1.0})
    for i in idx[1:]:
        out = out * MV.from_dict({(i,): 1.0})
    return out


