def I4_maps_L_to_Q():
    """[DERIVED] The Hodge map I4· interchanges the orbits: I4·(L-biv) is a Q-biv.
    This is the structure underlying both the chiral split and the L<->Q photon."""
    for name, b in L_BIVECTORS.items():
        img = I4 * b
        assert is_Q_bivector(img), f"I4·{name} should be a Q-bivector, got {img}"
    return True

def triple_product_Q():
    """[DERIVED] Sec 8.2: e14·e24·e34 = -I4  (the Q-orbit bivector three-body relation;
    docstring mislabel 'L-orbit' fixed 2026-07-02 — e14/e24/e34 are Q_BIVECTORS)."""
    return e(1, 4) * e(2, 4) * e(3, 4)

def triple_product_color():
    """[DERIVED] Sec 8.2: e124·e134·e234 = e4  (the color-singlet three-body relation)."""
    return e(1, 2, 4) * e(1, 3, 4) * e(2, 3, 4)

def hypercharge(B: MV) -> float:
    """[DERIVED] Sec 18.2: Y is the eigenvalue of the e4-bilinear  ~B e4 B = Y·e4.
    Computed from the blade alone — NO charge input. lepton e123 -> -1; each quark -> +1."""
    res = B.reverse() * e(4) * B
    y = res.coeff((4,))
    # the map must return a pure multiple of e4 (eigenvector check)
    assert abs((res - y * e(4)).coeff(()) ) < 1e-9 and len((res - y*e(4)).terms) == 0, \
        f"e4-bilinear not a pure e4 multiple for {B}: {res}"
    return y


