# ---- 5.3  algebra dimensions (Cl(4,0) and Cl(4,1) are NOT isomorphic) -----------
def cl_dimension(p_plus_q: int) -> int:
    """[DERIVED] real dimension of Cl(n) = 2^n.  Cl(4,0): 16.  Cl(4,1): 32."""
    return 2 ** p_plus_q

def cl40_vs_cl41():
    """[DERIVED] §5.3: different real dimensions (16 vs 32) ⇒ NOT isomorphic.
    Cl(4,0) is the spatial/wavefront algebra; Cl(4,1) carries the wave + meta-time."""
    return {"Cl(4,0)": cl_dimension(4), "Cl(4,1)": cl_dimension(5),
            "isomorphic": cl_dimension(4) == cl_dimension(5)}


