    m = _np.array([0.000511, 0.10566, 1.77686])          # lepton masses = the eigenvalues
    M0 = _np.diag(m)
    rng = _np.random.default_rng(0)
    def _U(n):
        A = rng.standard_normal((n, n)) + 1j * rng.standard_normal((n, n))
        Q, R = _np.linalg.qr(A)
        return Q @ _np.diag(_np.diag(R) / _np.abs(_np.diag(R)))
