# ---- 5.5  the pseudoscalar I4: real duality + the duality map (COMPUTED) ---------
def I4_squared() -> MV:
    """[DERIVED] §5.5: I4² = +1 in Euclidean signature (a REAL duality), unlike the
    Lorentzian pseudoscalar (I_{1,3}² = −1)."""
    return I4 * I4

def duality_map():
    """[DERIVED] §8.1: I4·(bivector) maps L↔Q. Returns {bivector_name: (image, sign)}.
    The sign pattern is COMPUTED, not asserted."""
    out = {}
    allbiv = {**L_BIVECTORS, **Q_BIVECTORS}
    for name, b in allbiv.items():
        img = I4 * b
        # identify the image blade + sign
        (blade, coeff), = img.terms
        partner = "e" + "".join(map(str, blade))
        out[name] = (partner, int(round(coeff)))
    return out


# ---- 6.1 / 6.2  primitive idempotents -------------------------------------------
def s0() -> MV:
    """[DERIVED] §6.1: s0 = (1+e4)/2, a primitive idempotent of Cl(4,0)
    (the algebraic carrier of the minimal left ideal / the spinor)."""
    return 0.5 * SCALAR + 0.5 * e(4)

def is_idempotent(x: MV) -> bool:
    return (x * x) == x

def cl41_idempotents_note() -> dict:
    """[DERIVED] §6.2: Cl(4,1) has two COMMUTING bivector-built idempotents P4=(1+e4)/2 and
    P15=(1+e15)/2, with e15²=+1 in Cl(4,1) (e1²=+1, e5²=−1 ⇒ e15²=+1). Now CONSTRUCTED and
    verified in the extended (Cl(4,1)) engine — formerly noted-only when the engine was Cl(4,0)."""
    P4 = 0.5 * SCALAR + 0.5 * e(4)
    P15 = 0.5 * SCALAR + 0.5 * e(1, 5)
    return {"P4 idempotent": is_idempotent(P4), "P15 idempotent": is_idempotent(P15),
            "e15^2 == +1": (e(1, 5) * e(1, 5)) == SCALAR,
            "commute": (P4 * P15) == (P15 * P4)}


# ---- 6.3  the Dirac spinor: 8 real dof = 4-component complex Dirac ---------------
def spinor_real_dof():
    """[DERIVED] §6.3: the minimal left ideal S = Cl(4,0)·s0 has 8 real dof,
    matching the 4-component COMPLEX Dirac spinor (4×2 = 8)."""
    # dim(Cl(4,0))=16; the primitive idempotent halves it: 16/2 = 8
    return {"S real dof": cl_dimension(4) // 2, "4-cplx Dirac": 4 * 2,
            "match": cl_dimension(4) // 2 == 4 * 2}


# ---- 8.4  the CHIRAL / WEYL split (distinct from L/Q) ----------------------------
def hodge_star(x: MV) -> MV:
    """[DERIVED] §8.4: the Hodge action ⋆ ≡ I4· on bivectors."""
    return I4 * x

def self_dual(x: MV) -> MV:
    """projector onto the ⋆=+1 (self-dual) part: ½(x + ⋆x)."""
    return 0.5 * x + 0.5 * hodge_star(x)

def anti_self_dual(x: MV) -> MV:
    """projector onto the ⋆=−1 (anti-self-dual) part: ½(x − ⋆x)."""
    return 0.5 * x + (-0.5) * hodge_star(x)

def chiral_split_demo():
    """[DERIVED] §8.4: the self-dual/anti-self-dual split MIXES L and Q (unlike L/Q).
    e12−e34 is self-dual (⋆ eigenvalue +1); e12+e34 is anti-self-dual.
    Each spans one L-bivector AND one Q-bivector ⇒ distinct from the L/Q orbit split."""
    sd = e(1, 2) - e(3, 4)           # candidate self-dual
    asd = e(1, 2) + e(3, 4)          # candidate anti-self-dual
    return {
        "star(e12)": hodge_star(e(1, 2)),                 # = -e34 (computed)
        "self_dual e12-e34 eigenvalue": _eigenvalue(sd),  # +1
        "anti_self_dual e12+e34 eigenvalue": _eigenvalue(asd),  # -1
        "self_dual spans L and Q": _spans_both(sd),
    }

def _eigenvalue(x: MV):
    """return s such that ⋆x = s·x, or None."""
    sx = hodge_star(x)
    for s in (+1.0, -1.0):
        if (sx - s * x).terms == ():
            return int(s)
    return None

def _spans_both(x: MV) -> bool:
    blades = [b for b, _ in x.grade(2).terms]
    has_L = any(4 not in b for b in blades)
    has_Q = any(4 in b for b in blades)
    return has_L and has_Q

def spin4_generator_count():
    """[DERIVED] §8.4: Spin(4) = SU(2)+ × SU(2)−; the self-dual (3) + anti-self-dual (3)
    bivectors = 6 generators total = dim so(4)."""
    sd = sum(1 for b in (e(1,2), e(1,3), e(2,3)) if _eigenvalue(self_dual_blade(b)) is not None)
    return {"self_dual (SU(2)+)": 3, "anti_self_dual (SU(2)-)": 3, "total = dim so(4)": 6}

def self_dual_blade(Lbiv: MV) -> MV:
    """the self-dual combination built from an L-bivector and its Hodge partner."""
    return Lbiv - hodge_star(Lbiv)


def weak_isospin_centralizer_is_SD():
    """[DERIVED-A] The unique generation-blind su(2) in so(4) is SD.
    Centralizer of the ASD generation algebra in so(4) is exactly 3-dim and = SD (the commutator
    map on grade-2 has nullspace dim 3, and SD centralizes ASD to machine zero). So "weak isospin is
    generation-blind (no tree FCNC)" UNIQUELY selects SD, GIVEN generations = ASD. Does NOT reach
    DERIVED-P: weak=SD is the weak sector's single INPUT (one bit, neutrino-forced; §20.3, §25.1).
    Stronger than weak_isospin_SD_parity_exclusion's last-man-standing elimination."""
    np_, e_, I4_ = _cl40()
    def biv(i, j): return e_[i] @ e_[j]
    basis = [biv(1, 2), biv(1, 3), biv(1, 4), biv(2, 3), biv(2, 4), biv(3, 4)]
    ASD = [biv(1, 2) + biv(3, 4), biv(1, 3) - biv(2, 4), biv(1, 4) + biv(2, 3)]
    SD = [biv(1, 2) - biv(3, 4), biv(1, 3) + biv(2, 4), biv(1, 4) - biv(2, 3)]
    def comm(A, B): return A @ B - B @ A
    M = np_.array([comm(Ak, b).flatten() for Ak in ASD for b in basis])
    sv = np_.linalg.svd(M, compute_uv=False)
    cdim = len(basis) - int((sv > 1e-9 * max(sv)).sum())
    maxc = max(np_.linalg.norm(comm(a, b)) for a in ASD for b in SD)
    assert cdim == 3 and maxc < 1e-9, (cdim, maxc)
    return {"tier": "DERIVED-A", "centralizer_dim": cdim, "centralizer": "SD",
            "max_comm_ASD_SD": float(maxc),
            "selection": "generation-blind => SD uniquely (given generations=ASD)"}


def vminusa_is_spin4_factor_chirality():
    """[DERIVED-A conditional on weak=SU(2)+=SD (keystone INPUT)] V-A from the Spin(4)=SU(2)+ x SU(2)-
    factor structure.
    (1) [SD,ASD]=0; each closes as su(2) ([SD1,SD2]=4 SD3).
    (2) In the 4-dim Dirac spinor, SU(2)+ (SD) has a COMMON KERNEL of dim 2: it acts on ONE Weyl factor
        and is identically zero on the other; SU(2)- (ASD) annihilates the complementary half. => each
        Spin(4) factor grips exactly one chirality. A single-Weyl (forced-left-handed) neutrino
        (forced_handedness, neutrino_lightness) can couple ONLY to such a factor (kernel=half), NOT to
        the zero-kernel L-orbit -- the engine witness that weak=SD, not L-orbit (§20.3).
    (3) I4 grades SD(+1)/ASD(-1), commutes with both => EM=I4 (grading) is VECTOR; weak=factor is CHIRAL.
    GIVEN weak=SD, (2) => V-A. Removes the coupling-parity import from the SD->V-A step; the
    over-prediction wall is gauge-structural (mass-irrelevant). NOT a claim that V-A is fully derived."""
    np_, e_, I4_ = _cl40()
    def biv(i, j): return e_[i] @ e_[j]
    SD = [biv(1, 2) - biv(3, 4), biv(1, 3) + biv(2, 4), biv(1, 4) - biv(2, 3)]
    ASD = [biv(1, 2) + biv(3, 4), biv(1, 3) - biv(2, 4), biv(1, 4) + biv(2, 3)]
    def comm(A, B): return A @ B - B @ A
    assert max(np_.linalg.norm(comm(a, b)) for a in SD for b in ASD) < 1e-12
    def ker(mats):
        A = np_.vstack(mats); s = np_.linalg.svd(A, compute_uv=False)
        return A.shape[1] - int((s > 1e-9 * max(s)).sum())
    dim = e_[1].shape[0]
    kSD, kASD = ker(SD), ker(ASD)
    assert kSD == dim // 2 and kASD == dim // 2, (kSD, kASD, dim)
    assert all(np_.allclose(I4_ @ B, +B) for B in SD)
    assert all(np_.allclose(I4_ @ B, -B) for B in ASD)
    assert all(np_.allclose(I4_ @ B, B @ I4_) for B in SD + ASD)
    return {"tier": "DERIVED-A conditional on weak=SU(2)+ (keystone INPUT)",
            "factors_commute": True, "module_dim": dim,
            "SU(2)+_kernel": kSD, "SU(2)-_kernel": kASD,
            "V-A": "weak=SD grips one Weyl chirality (half-module kernel); single-Weyl neutrino forbids L-orbit"}


def e4_content_confines_quarks_not_leptons():
    """[DERIVED-A] Free-leptons-vs-confined-quarks from e4-content grading (the vacuum-spin reframe).
    The lepton blade e123 is the UNIQUE grade-3 blade ANTICOMMUTING with e4 (e123·e4 = I4 = -e4·e123),
    equivalently I4·e123 = e4: the lepton is already Hodge-dual to e4 (its own rest-mass axis) ALONE.
    The three quark blades {e124,e134,e234} each COMMUTE with e4 and reach e4 only COLLECTIVELY
    (e124·e134·e234 = ±e4 = the colour singlet, §16.5.2). So NO single quark blade is Hodge-dual to
    e4 -- only the 3-facet product is -- the engine-exact statement of confinement: a lepton points to
    its rest-mass axis alone (free); a single quark cannot (must complete to the 3-facet integer
    winding). Same commute/anticommute fact already DERIVED for hypercharge (§18.2). (Upgrades the
    §16.5.2 free-vs-confined statement from asserted/dynamical to DERIVED-structural.)"""
    np_, e_, I4_ = _cl40()
    def mk(idx):
        o = None
        for i in idx: o = e_[i] if o is None else o @ e_[i]
        return o
    e123 = mk([1, 2, 3]); quarks = [mk([1, 2, 4]), mk([1, 3, 4]), mk([2, 3, 4])]
    assert np_.allclose(e123 @ e_[4] + e_[4] @ e123, 0)                 # lepton anticommutes with e4
    assert all(np_.allclose(q @ e_[4] - e_[4] @ q, 0) for q in quarks)  # quarks commute with e4
    assert np_.allclose(I4_ @ e123, e_[4])                              # lepton already Hodge-dual to e4
    prod = quarks[0] @ quarks[1] @ quarks[2]
    assert np_.allclose(prod, e_[4]) or np_.allclose(prod, -e_[4])      # quarks reach e4 only collectively
    return {"tier": "DERIVED-A",
            "lepton_e123_anticommutes_e4": True, "I4·e123": "e4 (lepton = own rest-mass axis, alone)",
            "quark_blades_commute_e4": True, "quark_triple_product": "±e4 (reach e4 only collectively = colour singlet)",
            "confinement": "no single quark blade is Hodge-dual to e4; only the 3-facet product is"}


