def gammas():
    """γ⁰=e4, γʲ=e4·ej  (the §12 wavefront construction)."""
    return [e(4), e(4) * e(1), e(4) * e(2), e(4) * e(3)]

def comm(x: MV, y: MV) -> MV:
    """commutator [x,y] = xy - yx."""
    return x * y - y * x

def exp_unit_bivector(B: MV, theta: float) -> MV:
    """[internal helper / primitive] exp(B·θ) for a UNIT bivector B (B²=-1): = cos θ + B·sin θ.
    (Checks B²≈-1 within float tolerance so misuse is caught.)"""
    b2 = (B * B).coeff(())
    assert abs(b2 + 1.0) < 1e-9, f"exp_unit_bivector needs B²=-1, got scalar part {b2}"
    return math.cos(theta) * SCALAR + math.sin(theta) * B


# ---- §13.3 boost & rotation generators ----------------------------------------
def boost(j: int) -> MV:
    """[DERIVED] §13.3: K_j = ½ γ⁰γʲ = ½ e_j  (a Cl(4,0) VECTOR; K_j² = +¼, non-compact)."""
    g = gammas()
    return 0.5 * (g[0] * g[j])

def rotation(i: int, j: int) -> MV:
    """[DERIVED] §13.3: J = ½ γʲγᵏ = -½ e_jk  (bivector; J² = -¼, compact)."""
    g = gammas()
    return 0.5 * (g[i] * g[j])


# ---- §13.4 Thomas precession + §13.5 so(1,3) closure --------------------------
def thomas_KK(i: int, j: int):
    """[DERIVED] §13.4: [K_i,K_j] = ½ e_ij = -ε_ijk J_k — the MINUS sign marks so(1,3)."""
    return comm(boost(i), boost(j))

def so13_closure_signs():
    """[DERIVED] §13.5: [J_i,J_j]=+ε J_k, [J_i,K_j]=+ε K_k, [K_i,K_j]=-ε J_k.
    Returns the three structure signs as computed (the boost-boost sign is the key one)."""
    # J_3 = ½γ¹γ² (rotation in 1-2), K_1=½e1, K_2=½e2
    J3 = rotation(1, 2)
    KK = thomas_KK(1, 2)                 # [K1,K2]
    JJ = comm(rotation(2, 3), rotation(3, 1))  # [J1,J2] type
    JK = comm(rotation(1, 2), boost(1))        # [J3,K1] type
    return {
        "[K1,K2] = -J3 (boost-boost gives MINUS rotation = so(1,3))": KK == (-1.0) * J3,
        "[K1,K2]": KK, "J3": J3,
    }


# ---- §14.7 Hestenes Dirac: Iσ³ = e12 in the wavefront frame --------------------
def hestenes_Isigma3() -> MV:
    """[DERIVED] §14.7: I = γ⁰γ¹γ²γ³ (Cl(1,3) pseudoscalar), σ³ = γ³γ⁰.
    In the wavefront frame Iσ³ = e12 (the right-acting unit that plays the role of i)."""
    g = gammas()
    I = g[0] * g[1] * g[2] * g[3]
    sigma3 = g[3] * g[0]
    return I * sigma3

def dirac_ideal_idempotent() -> MV:
    """[DERIVED] §14.7: P_+ = ½(1+γ⁰), idempotent; the ideal on which ψγ⁰=ψ."""
    return 0.5 * SCALAR + 0.5 * gammas()[0]


# ---- §15.4 Bell / Tsirelson ----------------------------------------------------
def half_angle_overlap(dtheta: float) -> float:
    """[DERIVED] §15.4: ⟨ψ_a|ψ_b⟩ = ⟨exp((θ_b-θ_a)e12/2)⟩_0 = cos(Δθ/2).
    The ½ is the Spin(3) double-cover half-angle (R(2π)=-1). COMPUTED via exp."""
    R = exp_unit_bivector(e(1, 2), dtheta / 2.0)
    return R.coeff(())                     # scalar part = cos(Δθ/2)

def bell_correlation(a: float, b: float) -> float:
    """[DERIVED] §15.4: singlet correlation E(a,b) = -cos(θ_ab)  (a,b = measurement angles, rad)."""
    return -math.cos(a - b)

def chsh_S(a, ap, b, bp) -> float:
    """CHSH combination S = E(a,b) - E(a,b') + E(a',b) + E(a',b')."""
    return (bell_correlation(a, b) - bell_correlation(a, bp)
            + bell_correlation(ap, b) + bell_correlation(ap, bp))

def tsirelson_S() -> float:
    """[DERIVED] §15.4: at optimal angles (0, π/2, π/4, 3π/4), |S| = 2√2 — Tsirelson, exactly."""
    return abs(chsh_S(0.0, math.pi/2, math.pi/4, 3*math.pi/4))

def mermin_value() -> float:
    """[DERIVED] §15.4 (multipartite): the 3-party Mermin/GHZ value |M| = 4 — the QM/GHZ maximum
    exactly (classical LHV bound = 2), extending the two-party Tsirelson result (2√2) to n=3.
    Built as the grade-0 part of three COPLANAR e12-rotors:
        E3(φ1,φ2,φ3) = ⟨exp(φ1·e12) exp(φ2·e12) exp(φ3·e12)⟩_0 = cos(φ1+φ2+φ3),
    evaluated at the GHZ-optimal Mermin settings X↔0, Y↔π/2. Per §14.7 e12 is the geometric i,
    so the per-qubit phase IS the rotor — TWT-native, no new ontology (only the bedrock rotor
    field + the existing e12-plane grade-0 projection). A consistency confirmation, not a falsifier:
    TWT reproduces the GHZ value because QM is the medium read by the wavefront-locked observer.
    NB (methodological): the naive grade-0 of three measurement VECTORS ⟨â b̂ ĉ⟩_0 is identically 0
    (a product of three vectors carries only grades 1,3) — the correct multipartite object is rotor
    composition, not the vector product. Scope: n=3, GHZ/symmetric class, optimal settings."""
    def _E3(p1, p2, p3):
        R = (exp_unit_bivector(e(1, 2), p1) * exp_unit_bivector(e(1, 2), p2)
             * exp_unit_bivector(e(1, 2), p3))
        return R.coeff(())                 # scalar (grade-0) part = cos(p1+p2+p3)
    X, Y = 0.0, math.pi/2
    M = _E3(X, X, X) - _E3(X, Y, Y) - _E3(Y, X, Y) - _E3(Y, Y, X)
    return abs(M)


def mermin_klyshko_value(n: int) -> float:
    """[DERIVED, no new ontology] §15.4 (multipartite, general n): the n-party
    Mermin–Klyshko (MK) value for the GHZ state at MK-optimal settings, extending
    mermin_value (n=3) to the full hierarchy. Built from the SAME TWT object — the
    grade-0 part of n coplanar e12-rotors,
        E_n(φ_1..φ_n) = ⟨∏_j exp(φ_j·e12)⟩_0 = cos(Σ_j φ_j),
    which is exactly the GHZ correlation ⟨GHZ|∏(cosφ σ_x+sinφ σ_y)|GHZ⟩ (Mermin).
    The MK polynomial is the standard Belinskii–Klyshko recursion
        M_k = ½(M_{k-1}(A_k+A_k') + M'_{k-1}(A_k−A_k')),   M_1 = 2·A_1,
    where M'_{k-1} swaps all primes. The M_1 = 2·A_1 start is the convention whose QM
    bound is 2^((n+1)/2) (arXiv:2303.12195); plain M_1=A_1 gives the 2^((n-1)/2)
    normalization — a pure factor-of-2 convention, not physics.
    Evaluated at the MK-OPTIMAL settings θ_j = −(j−1)π/(2n), θ_j' = θ_j + π/2
    (Tsirelson-type). ⚠ These are NOT the naive 0/π/2: that pattern maximizes the Mermin
    *eigenvalue* operator Re∏(σx+iσy) (GHZ eigenvalue 2^(n-1)), a DIFFERENT object that
    coincides with the MK Bell polynomial only at n=3; on the MK polynomial 0/π/2 yields
    only the classical bound 2 at even n.
    Returns |M_n| = 2^((n+1)/2) for all n — TWT reproduces the full QM-GHZ hierarchy
    (a consistency confirmation, NOT a falsifier): n=2 → 2√2 (Tsirelson), n=3 → 4
    (== mermin_value), n=4 → 4√2, n=5 → 8.
    NB (carried from mermin_value): the naive grade-0 of measurement VECTORS is ≡ 0; the
    correct multipartite object is rotor composition. Cost is O(2ⁿ) terms — for modest n.
    Scope: GHZ/symmetric class only; the W-state/non-GHZ class is a located construction
    gap — see w_state_located_gap() (§15.4.1, Cl-iv-c): the single-plane rotor economy does
    not extend off the GHZ class."""
    if n < 1:
        raise ValueError("MK hierarchy needs n ≥ 1")
    # MK polynomial as a signed sum over per-party prime-assignments (Belinskii–Klyshko)
    def _swap(terms):
        return [(c, tuple(not b for b in bits)) for (c, bits) in terms]
    M = [(2.0, (False,))]                         # M_1 = 2·A_1
    for _ in range(2, n + 1):
        Mp = _swap(M)
        nxt = []
        for (c, bits) in M:                       # M_{k-1}·(A_k + A_k')
            nxt += [(0.5 * c, bits + (False,)), (0.5 * c, bits + (True,))]
        for (c, bits) in Mp:                      # M'_{k-1}·(A_k − A_k')
            nxt += [(0.5 * c, bits + (False,)), (-0.5 * c, bits + (True,))]
        M = nxt
    # MK-optimal (Tsirelson-type) settings
    theta  = [-(j) * math.pi / (2 * n) for j in range(n)]   # j=0..n-1 ≡ (j−1) one-indexed
    primed = [t + math.pi / 2 for t in theta]
    # evaluate each correlation as the grade-0 of composed e12-rotors (TWT-native)
    def _E(phases):
        R = exp_unit_bivector(e(1, 2), phases[0])
        for p in phases[1:]:
            R = R * exp_unit_bivector(e(1, 2), p)
        return R.coeff(())
    total = 0.0
    for (c, bits) in M:
        phases = [primed[j] if b else theta[j] for j, b in enumerate(bits)]
        total += c * _E(phases)
    return abs(total)


def _E_W_qm(theta, phi):
    """The QM 3-qubit W correlation E_W = <W| s·n1 ⊗ s·n2 ⊗ s·n3 |W>,
    n_j = (sin t cos p, sin t sin p, cos t). DERIVED closed form, verified against the
    brute-force Pauli-tensor object to 4.4e-16 (TASK 5; reconciler re-verified):
        E_W = -C1 C2 C3 + (2/3) Σ_{j<k} S_j S_k C_l cos(phi_j - phi_k),
    with C=cos theta, S=sin theta, l the third index. Contrast GHZ: S1 S2 S3 cos(Σphi)."""
    C = [math.cos(t) for t in theta]; S = [math.sin(t) for t in theta]
    pair = (S[0]*S[1]*C[2]*math.cos(phi[0]-phi[1])
            + S[0]*S[2]*C[1]*math.cos(phi[0]-phi[2])
            + S[1]*S[2]*C[0]*math.cos(phi[1]-phi[2]))
    return -C[0]*C[1]*C[2] + (2.0/3.0)*pair


def w_state_located_gap():
    """[LOCATED-GAP, outcome ii-a] §15.4.1 (proposed): the W (non-GHZ) class.

    The §15.4 GHZ object O_GHZ = <prod_j exp(phi_j e12)>_0 = cos(Σ phi_j) reproduces the
    GHZ class (mermin_value=4, the full MK ladder) because the GHZ correlation IS the
    single collective in-plane phase. It does NOT extend to the W class, for two linked,
    proven reasons (this function's asserts):

      P1 (second plane):  W's correlation is identically 0 in the single e12 measurement
          plane, and its Mermin optimum |M3|=3.046 is reached only with sigma_z-
          (out-of-plane) settings. The library object has a phi (azimuth) slot per wing
          and NO polar slot -- its parameter space does not even contain the W-optimal
          settings. W needs support on >=2 non-commuting rotation planes.
      P2 (sum over wings): GHZ depends on the phase SUM (co-planar rotors compose
          additively -> a PRODUCT). W depends on pairwise phase DIFFERENCES, organised as
          |sum_j e^{i phi_j}|^2 -- the modulus-squared of a coherent symmetric SUM over
          wings (the single-excitation Dicke structure). That is a rotor SUM / norm, not a
          product; a single-plane sum is positive-definite, so the cos(theta_l) out-of-plane
          weights of P1 are exactly what reconcile it with W (e.g. the in-plane value 0).

    MERMIN OPERATOR (read this to avoid the Task-4 collision from the other side): the W
    anchors 4 / 3.046 / 3 live under Mermin's ORIGINAL 1990 form
        M3 = ABC - AB'C' - A'BC' - A'B'C   (even-prime / eigenvalue pattern),
    NOT the Belinskii-Klyshko polynomial A'BC+AB'C+ABC'-A'B'C' used in mermin_klyshko_value
    (a different object with different optimal settings). Under Mermin 1990, GHZ at (sz,sx)
    is 0 and GHZ's max-4 sits at (sx,sy); W reaches 3 at (sz,sx) and 3.046 at its optimum.
    (mermin_value uses the Mermin-1990 form at in-plane sx/sy-type settings, giving the
    GHZ 4 -- consistent.)

    Located missing construction (the deliverable form):
      W-state correlations need the TWT object to have property P =
        { the MULTIPARTICLE correlator -- n independent copies of the even subalgebra
          Cl+(4,0) ~ H (+) H (Doran-Lasenby multiparticle GA, which QM's tensor product
          realises), restricted to the symmetric single-excitation Dicke sector
          |J=n/2, m=n/2-1>, carried on two non-commuting bivector planes (one azimuthal
          e12, one polar) },
        sourced from [bedrock: the rotor field is defined across ALL wings of the substrate
          (n-copy/multiparticle + symmetric superposition), and all six bivector planes
          {L: e12,e13,e23 ; Q: e14,e24,e34} are available substrate rotation planes].
      The rotor grade-0 captures the GHZ class because GHZ is a single collective phase in
      one plane (one copy, one plane suffice); the W class needs the richer sum-over-wings,
      two-plane, n-copy object.

    HONEST CONCESSION (this IS the content, not a caveat): the named object (full
    multiparticle correlator) is isomorphic to general multi-qubit QM, so it reproduces W
    WITHOUT being a novel TWT-specific economy. The finding is therefore that the elegant
    single-plane shortcut that made the GHZ class parameter-free does NOT survive to W --
    not that "TWT cannot do W". The library product is exactly the GHZ-sector, single-plane
    restriction of this object.

    OPEN refinement (named for the next team): P1/P2 are airtight; the demonstrated failure
    of the *natural single-copy two-plane* object is failure-by-construction, not a full
    impossibility proof. Whether some engineered single-copy two-plane object could reach
    E_W (vs strictly needing n copies) is the next lemma -- though any such object lacking a
    bedrock motivation would be the reverse-engineered fit the construction discipline forbids."""
    import cmath, random
    cos, sin, pi = math.cos, math.sin, math.pi
    out = {}

    # --- P0: the GHZ object is the collective single-plane phase ---
    def O_lib(p):
        R = (exp_unit_bivector(e(1, 2), p[0]) * exp_unit_bivector(e(1, 2), p[1])
             * exp_unit_bivector(e(1, 2), p[2]))
        return R.coeff(())
    random.seed(0)
    smp = [[random.uniform(0, 2*pi) for _ in range(3)] for _ in range(200)]
    assert max(abs(O_lib(p) - cos(p[0]+p[1]+p[2])) for p in smp) < 1e-9
    out["GHZ_object"] = "<prod_j exp(phi_j e12)>_0 = cos(sum phi_j)  [single copy, single plane]"

    # --- P1: W vanishes in the e12 plane; optimum is out-of-plane ---
    inplane = [abs(_E_W_qm([pi/2]*3, [random.uniform(0, 2*pi) for _ in range(3)])) for _ in range(300)]
    assert max(inplane) < 1e-12                          # W correlation == 0 in the e12 plane
    assert abs(_E_W_qm([0, 0, 0], [0, 0, 0]) + 1.0) < 1e-12  # pure sigma_z (out-of-plane) nonzero (= -1)
    out["P1_second_plane"] = "W==0 in the single measurement plane; optimum out-of-plane -> needs >=2 planes"

    # --- P2: difference-phase / sum-over-wings is a norm (positive-definite) ---
    def O_sum_norm(p):
        O = (exp_unit_bivector(e(1, 2), p[0]) + exp_unit_bivector(e(1, 2), p[1])
             + exp_unit_bivector(e(1, 2), p[2]))
        return (O.reverse()*O).coeff(())
    p = [0.7, 1.9, 2.6]
    assert abs(O_sum_norm(p) - abs(sum(cmath.exp(1j*x) for x in p))**2) < 1e-9
    assert O_sum_norm(p) >= 0.0                           # a norm: cannot equal W's in-plane 0
