# ---- TASK weak-isospin: the rank criterion → (iii) UNDER-DETERMINED (2026-06-23) ----
# Proper two-build (separate MC + Reviewer + neutral Coordinator). The CKM verdict depends on TWO
# unforced choices: U1 the SU(2)_L bivector embedding, U2 the quark generation space. The rank of the
# embedding's action on the gen-space decides democratic (0) vs mixing-reachable (≥2). Reuses _ip above.
def _nrm(np, B):
    return B / np.sqrt(abs(_ip(np, B, B)))

def _Wembeddings(e):
    import math
    su2p = [_biv(e,1,2)-_biv(e,3,4), _biv(e,1,3)+_biv(e,2,4), _biv(e,2,3)-_biv(e,1,4)]   # §8.4 self-dual
    Lfr  = [_biv(e,1,2), _biv(e,1,3), _biv(e,2,3)]                                          # §8.2/§10.5 spatial SO(3)
    asd  = [_biv(e,1,2)+_biv(e,3,4), _biv(e,1,3)-_biv(e,2,4), _biv(e,1,4)+_biv(e,2,3)]      # anti-self-dual
    th = 0.3; handed = [math.cos(th)*su2p[i]+math.sin(th)*asd[i] for i in range(3)]
    return {"su2_plus_(§8.4)": su2p, "L_frak_(§10.5)": Lfr, "handed_(§19.8.1 lead)": handed}, asd

def _Wgenspaces(e):
    return {"Q_orbit_(§8.3 quark gens)": [_biv(e,1,4),_biv(e,2,4),_biv(e,3,4)],
            "anti_self_dual_(prior arc)": [_biv(e,1,2)+_biv(e,3,4),_biv(e,1,3)-_biv(e,2,4),_biv(e,1,4)+_biv(e,2,3)]}

def _Wrank(np, e, embed, gens):
    un = [_nrm(np, g) for g in gens]; rows = []
    for B in embed:
        for Uj in un:
            X = (B @ Uj - Uj @ B) / 2
            rows.append([_ip(np, Ui, X) for Ui in un])
    return int(np.linalg.matrix_rank(np.array(rows), tol=1e-9))

def weak_isospin_rank_table():
    """[DERIVED] Rank of each SU(2)_L embedding's action on each candidate quark generation space
    (0→democratic; 1→one Cabibbo angle; ≥2→ladder room). The prior (a)/democratic (rank 0) appears
    ONLY for (su(2)+, anti-self-dual); on §8.3's STATED Q-orbit generations EVERY embedding gives rank 3.
    self-check: that one cell is 0, all Q-orbit cells are 3, and the rank-0 count over the grid is 1."""
    np, e, _ = _cl40(); emb, _ = _Wembeddings(e); gs = _Wgenspaces(e)
    table = {en: {gn: _Wrank(np, e, eb, gv) for gn, gv in gs.items()} for en, eb in emb.items()}
    assert table["su2_plus_(§8.4)"]["anti_self_dual_(prior arc)"] == 0
    assert all(table[en]["Q_orbit_(§8.3 quark gens)"] == 3 for en in emb)
    assert sum(1 for en in emb for gn in gs if table[en][gn] == 0) == 1
    return table

