    rngp = np.random.default_rng(11); all_perm = True; any_nonid = False
    for _ in range(300):
        pu, pd = rngp.uniform(0, 2*math.pi, 2)
        _, Vu = np.linalg.eigh(circ(b_u, eps_u, pu)); _, Vd = np.linalg.eigh(circ(b_d, eps_d, pd))
        Pp = np.abs(Vu.conj().T @ Vd)
