    out["all_generators_square_to_minus1"] = all(abs((g * g).coeff(()) + 1.0) < 1e-12 for g in gens.values())
    assert out["all_generators_square_to_minus1"], "compactness: all orientation generators must square to -1"

    # (B3) grade-2 orientation rotors are UNIT-NORM under reverse for ALL twist angles
