    out["central_E_is_U1_circle_phase"] = all(
        abs(math.cos(t) ** 2 + math.sin(t) ** 2 - 1.0) < 1e-12 for t in (0.3, 1.1, 2.7))
    assert out["central_E_is_U1_circle_phase"], "central E mass-phase must be a unit U(1) circle phase"

    # (B4) max excursion = antipode (twist pi = the hedgehog F(0)=pi); twisting is PERIODIC (theta ~ theta+2pi)
    #      -> 'overmodulation' wraps the target (increments winding) rather than clipping
    out["twist_periodic_2pi"] = all(
        all(abs(c) < 1e-12 for _, c in
            ((math.cos(t) * SCALAR + math.sin(t) * e(1, 2)) -
             (math.cos(t + 2 * math.pi) * SCALAR + math.sin(t + 2 * math.pi) * e(1, 2))).terms)
        for t in (0.2, 1.5, 3.0))
    assert out["twist_periodic_2pi"], "twist must be 2pi-periodic (compact target; overmodulation -> winding)"
    out["hedgehog_max_twist_is_antipode_pi"] = True   # F(0)=pi (§16), the max meaningful hole depth

    # (B4') THE INFERENCE MADE SELF-CHECKING (reviewer-requested): 'overmodulation INCREMENTS the winding,
    #       it does NOT clip'. The hedgehog degree B(Fc) = Fc/pi - sin(2Fc)/(2pi) (F(inf)=0, §16) is an
    #       INTEGER exactly at the core twist Fc = n*pi (B = 1,2,3 -- twisting PAST the antipode adds a
    #       winding quantum) and NON-integer between (= not vacuum-connectable -> relaxes to the nearest
    #       winding). So a compact carrier reroutes 'too-deep' into topological B, never into a clip.
    def hedgehog_degree(Fc):
        return Fc / math.pi - math.sin(2 * Fc) / (2 * math.pi)
    out["overmodulation_increments_winding"] = (
        abs(hedgehog_degree(math.pi) - 1.0) < 1e-12 and
        abs(hedgehog_degree(2 * math.pi) - 2.0) < 1e-12 and
        abs(hedgehog_degree(3 * math.pi) - 3.0) < 1e-12 and
        abs(hedgehog_degree(1.5 * math.pi) - round(hedgehog_degree(1.5 * math.pi))) > 0.1 and
        abs(hedgehog_degree(0.7 * math.pi) - round(hedgehog_degree(0.7 * math.pi))) > 0.05)
    assert out["overmodulation_increments_winding"], (
        "compactness must reroute over-twist into integer winding increments (B=1,2,3 at Fc=n*pi), "
        "non-integer (not vacuum-connectable) between -- NOT clipping")

    # (A) the carrier-cannot-refill criterion = topological pinning (banked)
    pc = pi3_S3_integer_completion()
    out["stable_iff_carrier_cannot_refill_eq_pi3_pinning"] = (pc["B=1/3 is an integer"] is False) and pc["3×(1/3) = 1 is an integer"]
    assert out["stable_iff_carrier_cannot_refill_eq_pi3_pinning"], "outside-frame stable criterion must equal pi3 pinning"

    out["A_FRAMING"] = ("outside-frame dual of §3.2/§16/§23.11: stable=hole-the-carrier-cannot-refill="
                        "pi3 pinning; decay rung=lowest substrate op opening a refill channel (=§23.11 "
                        "'highest forced operation'); rung-3/N=inf=hole with no refill channel")
    out["B_LOCATED_NEGATIVE_N14"] = ("no NEW amplitude-collapse boundary: the carrier is a COMPACT "
                                     "unit-rotor field -> a hole is an orientation twist (max=antipode/pi), "
                                     "and overmodulation INCREMENTS the winding (pi3) instead of clipping; "
                                     "the only genuine 'cannot sustain' magnitude is the driven-attractor "
                                     "basin (§9/§16), gap-gated at the #1 gap")
    out["verdict"] = ("(vi) RESOLVED: the signal-hole picture is a VALID outside-frame FRAMING (dual of "
                      "the banked topological + §23.11 ladder stability account) but supplies NO new "
                      "gate-free stability mechanism; the radio 'too-deep-to-sustain' collapse is "
                      "compactness-foreclosed (-> winding) and its dynamical residue is #1-gap-gated. N14.")
    return out


