# ---- §18.3a  lepton-quark weak universality as a theorem ------------------------
# (the duplicate s0() def that lived here was removed 2026-07-26 — identical to the §16 def above)
def e4_acts_as_identity_on_Splus() -> bool:
    """[DERIVED] §18.3a: e4·s0 = s0 (e4 = +1 on the e4=+1 ideal)."""
    return (e(4) * s0()) == s0()

def universality_theorem():
    """[DERIVED] §18.3a: quark trivector e_{ij4} and lepton bivector e_{ij} act
    IDENTICALLY on S+, because e_{ij4} = e_{ij}·e4 and e4=+1 there. Hence the weak
    coupling cannot distinguish them: g_weak(quark) = g_weak(lepton). COMPUTED on s0."""
    pairs = [((1, 2, 4), (1, 2)), ((1, 3, 4), (1, 3)), ((2, 3, 4), (2, 3))]
    results = {}
    for tri, biv in pairs:
        lhs = e(*tri) * s0()      # trivector on the ideal
        rhs = e(*biv) * s0()      # bivector on the ideal
        results[f"e{''.join(map(str,tri))}·s0 == e{''.join(map(str,biv))}·s0"] = (lhs == rhs)
    return results


