# ---- §21.2  the consolidated Maxwell equation ∇F = J --------------------------
def maxwell_grade_structure():
    """[DERIVED] §21.2: ∇F=J with ∇ grade-1 (∂_τ+∇₃) and F grade-2 (bivector). The
    geometric product of a grade-1 and a grade-2 lands ONLY in grades {1,3}. The four
    Maxwell laws are the components of this one statement: grade-1 part = J (source),
    grade-3 part = 0 (sourceless). COMPUTED: build generic grade-1 ∇ and grade-2 F,
    confirm ∇F ∈ {grade 1, grade 3} with no grade-0/2/4 part."""
    # generic grade-1 operator (distinct coeffs so nothing cancels accidentally)
    D = 2*e(1) + 3*e(2) + 5*e(3) + 7*e(4)
    # generic grade-2 field
    F = (11*e(1,2) + 13*e(1,3) + 17*e(1,4) + 19*e(2,3) + 23*e(2,4) + 29*e(3,4))
    DF = D * F
    grades_present = sorted({len(b) for b, _ in DF.terms})
    g1 = len(DF.grade(1).terms)   # 4 components in 4D
    g3 = len(DF.grade(3).terms)   # 4 components in 4D
    return {
        "grades of ∇F": grades_present,           # [1, 3]
        "no grade-0/2/4 part": grades_present == [1, 3],
        "grade-1 components (Gauss+Ampère = J)": g1,
        "grade-3 components (Faraday+no-monopole = 0)": g3,
        "total = 8 = 4 Maxwell vector eqs": g1 + g3,
    }

def maxwell_four_laws():
    """[DERIVED] §21.2: the named decomposition of ∇F=J on a spatial slice.
    No magnetic monopoles because F is a pure bivector — the grade-3 source vanishes."""
    return {
        "grade-1 scalar":      "∇·E = ρ            (Gauss)",
        "grade-1 3-vector":    "∇×B - ∂_τE/c = j   (Ampère–Maxwell)",
        "grade-3 3-vector":    "∇×E + ∂_τB/c = 0   (Faraday)",
        "grade-3 pseudoscalar":"∇·B = 0            (no monopoles)",
    }


# ---- §21.3  the Coulomb potential ---------------------------------------------
def coulomb_is_harmonic() -> bool:
    """[DERIVED] §21.3: static F obeys ∇₃²F_static = -J_static; the point-source
    Green's function F_static = Σ/(4πr) is harmonic away from the source.
    COMPUTED: ∇²(1/r) = 0 for r>0 (sympy, spherical Laplacian)."""
    r = sp.symbols('r', positive=True)
    lap = sp.diff(r**2 * sp.diff(1/r, r), r) / r**2   # radial part of ∇² in 3D
    return sp.simplify(lap) == 0

def coulomb_potential(Sigma1: float, Sigma2: float, R: float) -> float:
    """[DERIVED] §21.3: V(R) = (Σ₁·Σ₂)/(4πR). Same-chirality (Σ₁·Σ₂>0) → repulsion;
    opposite-chirality (Σ₁·Σ₂<0) → attraction. (Coulomb law + like-repels-like.)"""
    return (Sigma1 * Sigma2) / (4 * math.pi * R)

def coulomb_sign_rule():
    """[DERIVED] §21.3: the sign of V follows the chirality product."""
    return {
        "same-chirality (Σ₁Σ₂>0) → V>0 repulsion": coulomb_potential(+1, +1, 1.0) > 0,
        "opposite-chirality (Σ₁Σ₂<0) → V<0 attraction": coulomb_potential(+1, -1, 1.0) < 0,
    }



